import { useEffect, useRef, useState } from "react";
import HeroCard from "./HeroCard";
import { lerp, clamp, ease } from "./helpers";
import '../index.css';

const CARDS = [
  { id: 1,  label: "Vehicle RC",      angle: 180,   rotate: -14, z: 26 },
  { id: 2,  label: "DL Verification", angle: 147.3, rotate: 9,   z: 27 },
  { id: 3,  label: "KYC Check",       angle: 114.5, rotate: -6,  z: 28 },
  { id: 4,  label: "Aadhaar",         angle: 81.8,  rotate: 5,   z: 29 },
  { id: 5,  label: "Face Match",      angle: 49.1,  rotate: -9,  z: 29 },
  { id: 6,  label: "PAN Card",        angle: 16.4,  rotate: 12,  z: 28 },
  { id: 7,  label: "Fraud Alert",     angle: 343.6, rotate: -5,  z: 27 },
  { id: 8,  label: "Bank Verify",     angle: 310.9, rotate: 11,  z: 28 },
  { id: 9,  label: "Credit Score",    angle: 278.2, rotate: -5,  z: 29 },
  { id: 10, label: "Background Chk",  angle: 245.5, rotate: -10, z: 28 },
  { id: 11, label: "Employment",      angle: 212.7, rotate: 9,   z: 27 },
];

export default function HeroSection() {
  const [progress, setProgress] = useState(0);
  const [vw, setVw]             = useState(0);
  const sectionRef              = useRef(null);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const p = clamp(
        -el.getBoundingClientRect().top / (el.offsetHeight * 0.62),
        0, 1
      );
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const update = () => setVw(window.innerWidth);
    update();
    window.addEventListener("resize", update, { passive: true });
    return () => window.removeEventListener("resize", update);
  }, []);

  const targetFontVw  = 9.2;
  const targetFontMax = 148;
  const targetFontPx  = Math.min((vw * targetFontVw) / 100, targetFontMax);
  const animatedFontPx = lerp(targetFontPx * 0.44, targetFontPx, ease(clamp(progress / 0.75, 0, 1)));

  /*
   * Text exit effect — synced exactly with card fade-out window (progress 0.65 → 0.95).
   * Cards use: lerp(1, 0, clamp((progress - 0.65) / 0.3, 0, 1))
   * We match the same window for the text so they disappear together.
   */
  const textExitT   = ease(clamp((progress - 0.65) / 0.30, 0, 1));
  const textOpacity = lerp(1, 0, textExitT);
  const textScale   = lerp(1, 1.08, textExitT);   // subtle zoom-out feel as it fades

  return (
    <div ref={sectionRef} style={{ height: "300vh", position: "relative" }}>
      <div
        id="home-banner"
        style={{
          position: "sticky",
          top: 30,
          height: "100vh",
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Grid background */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage:
              "linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px)," +
              "linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)",
            backgroundSize: "clamp(32px, 4vw, 48px) clamp(32px, 4vw, 48px)",
          }}
        />

        {/* ── TITLE — exit effect applied via opacity + scale ── */}
        <div
          style={{
            position: "absolute",
            zIndex: 15,
            textAlign: "center",
            width: "98vw",
            maxWidth: "1300px",
            opacity: textOpacity,
            transform: `scale(${textScale})`,
            willChange: "opacity, transform",
          }}
        >
          <h1
            style={{
              fontFamily: "'Inter', sans-serif",
              fontSize: `${Math.max(animatedFontPx, 32)}px`,
              fontWeight: 900,
              color: "white",
              margin: 0,
              lineHeight: 1.05,
              whiteSpace: "normal",
              overflowWrap: "normal",
              wordBreak: "keep-all",
              letterSpacing: "-0.02em",
              willChange: "font-size",
            }}
          >
            Deception from
            <br />
            Click to the Doorstep
          </h1>
        </div>

        {/* ── SUBTITLE — same exit effect ── */}
        <div
          style={{
            position: "absolute",
            top: "62%",
            left: "50%",
            transform: `translateX(-50%) scale(${textScale})`,
            width: "98vw",
            maxWidth: "1300px",
            zIndex: 16,
            textAlign: "center",
            pointerEvents: "none",
            opacity: textOpacity,
            willChange: "opacity, transform",
          }}
        >
          <p
            style={{
              fontSize: "40px",
              fontWeight: 500,
              color: "white",
              margin: 0,
              lineHeight: 1.3,
              opacity: 0.88,
              marginTop: "30px",
            }}
          >
            A closer look at the risks in India's gig workforce.
          </p>
        </div>

        {/* ── Cards layer ── */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            overflow: "hidden",
            zIndex: 25,
          }}
        >
          {CARDS.map(c => (
            <HeroCard key={c.id} card={c} progress={progress} vw={vw} />
          ))}
        </div>
      </div>
    </div>
  );
}
